import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const MiniWave: React.FC<{ n: number; seed: number; f: number; h: number; color: string; on: number }> = ({ n, seed, f, h, color, on }) => (
  <div style={{ display: "flex", alignItems: "center", gap: h * 0.1, flex: 1, height: h }}>
    {Array.from({ length: n }).map((_, i) => {
      const base = 0.22 + 0.78 * Math.abs(Math.sin(i * 1.31 + seed * 3.7));
      const puls = 0.55 + 0.45 * Math.sin(f * 0.2 + i * 0.5 + seed);
      return <div key={i} style={{ flex: 1, height: Math.max(2, h * base * puls), borderRadius: 999, background: color, opacity: 0.35 + 0.55 * on }} />;
    })}
  </div>
);

const PickTrack: React.FC<PrimitiveProps> = ({ anim, fps, dark, frame }) => {
  const f = useCurrentFrame();
  const S = Math.min(frame.width / 1080, frame.height / 1920);
  const txt = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  const heading = String(anim.params?.heading ?? anim.text ?? "Get one of these ones");
  const rawTracks = Array.isArray(anim.params?.tracks) ? (anim.params?.tracks as unknown[]) : [];
  const tracks = (rawTracks.length ? rawTracks : ["TRACK 01", "TRACK 02", "TRACK 03"]).map((t) => String(t));
  const picked = Math.max(0, Math.min(tracks.length - 1, Number(anim.params?.picked ?? 1)));
  const pickLabel = String(anim.params?.pickLabel ?? "PICKED");

  const hs = (heading.length > 30 ? 62 : heading.length > 20 ? 72 : 84) * S;
  const hIn = spring({ frame: f, fps, config: { damping: 200, mass: 0.6 } });

  const lockAt = 84;
  let active = -1;
  if (f >= lockAt) active = picked;
  else if (f >= 62) active = Math.min(2, tracks.length - 1);
  else if (f >= 40) active = Math.min(1, tracks.length - 1);
  else if (f >= 20) active = 0;

  const lock = spring({ frame: f - lockAt, fps, config: { damping: 13, mass: 0.6 } });

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.body, alignItems: "center", justifyContent: "center" }}>
      <div style={{ width: "84%", display: "flex", flexDirection: "column", alignItems: "center", gap: 46 * S }}>
        <div
          style={{
            fontFamily: FONTS.display,
            fontWeight: FONTS.displayWeight,
            textTransform: "uppercase",
            fontSize: hs,
            lineHeight: 1,
            textAlign: "center",
            backgroundImage: headlineGradient(),
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            color: "transparent",
            opacity: hIn,
            transform: `translateY(${(1 - hIn) * 26 * S}px)`,
          }}
        >
          {heading}
        </div>

        <div style={{ width: "100%", display: "flex", flexDirection: "column", gap: 28 * S }}>
          {tracks.map((t, i) => {
            const start = 8 + i * 8;
            const cardIn = spring({ frame: f - start, fps, config: { damping: 200, mass: 0.7 } });
            const isActive = active === i;
            const isLocked = f >= lockAt && i === picked;
            const dim = active >= 0 && !isActive ? 0.45 : 1;
            const scale = (0.94 + 0.06 * cardIn) * (isActive ? 1.03 : 1) * (isLocked ? 1 + 0.02 * Math.max(0, 1 - lock) : 1);
            return (
              <div
                key={i}
                style={{
                  position: "relative",
                  display: "flex",
                  alignItems: "center",
                  gap: 24 * S,
                  padding: `${30 * S}px ${30 * S}px`,
                  background: COLORS.vellum,
                  borderRadius: 22 * S,
                  border: `${Math.max(2, 2.5 * S)}px solid ${isActive ? COLORS.teal : "rgba(255,255,255,0.10)"}`,
                  boxShadow: isActive ? `0 0 ${44 * S}px ${COLORS.teal}44, 0 18px 44px rgba(0,0,0,0.4)` : "0 14px 36px rgba(0,0,0,0.32)",
                  opacity: cardIn * dim,
                  transform: `translateY(${(1 - cardIn) * 34 * S}px) scale(${scale})`,
                }}
              >
                <div
                  style={{
                    color: isActive ? txt : muted,
                    fontFamily: FONTS.mono,
                    fontSize: 22 * S,
                    letterSpacing: 0.14 * 22 * S,
                    flex: "0 0 auto",
                  }}
                >
                  {t}
                </div>
                <MiniWave n={26} seed={i + 2} f={f} h={54 * S} color={isActive ? COLORS.tealBright : COLORS.inkSoft} on={isActive ? 1 : 0} />
                {isLocked ? (
                  <div
                    style={{
                      flex: "0 0 auto",
                      display: "flex",
                      alignItems: "center",
                      gap: 12 * S,
                      padding: `${10 * S}px ${18 * S}px`,
                      borderRadius: 999,
                      backgroundImage: headlineGradient(),
                      color: COLORS.ink,
                      fontWeight: 700,
                      fontSize: 19 * S,
                      letterSpacing: 0.08 * 19 * S,
                      whiteSpace: "nowrap",
                      opacity: Math.max(0, Math.min(1, lock)),
                      transform: `scale(${0.7 + 0.3 * Math.max(0, Math.min(1.1, lock))})`,
                    }}
                  >
                    <span style={{ fontFamily: FONTS.body }}>{pickLabel}</span>
                  </div>
                ) : null}
              </div>
            );
          })}
        </div>

        <div style={{ color: txt, opacity: 0, height: 0, textShadow: ENGRAVE_SHADOW }} />
      </div>
    </AbsoluteFill>
  );
};

export default PickTrack;
